#include <iostream>
#include <cmath>

struct Particle {
    float position[3];
    float density;
    float pressure;
};

size_t getNeighbors(const uint32_t *particleTable, size_t particleIndex, float h, uint32_t *&neighbors) {
    size_t count = 10;
    neighbors = const_cast<uint32_t*>(particleTable);
    return count;
}

float poly6Kernel(float r, float h) {
    float q = r / h;
    if (q > 1) {
        return 0.0f;
    }
    return pow((1 - q), 3);
}

void parallelDensityAndPressures(Particle *particles, const size_t particleCount, const size_t start, const size_t end, const uint32_t *particleTable, float mass, float poly6, float h, float h2, float selfDens, float restDensity, float gasConstant) {
    for (size_t i = start; i < end; ++i) {
        Particle &p = particles[i];
        float density = 0.0f;
        uint32_t* neighbors;
        size_t count = getNeighbors(particleTable, i, h, neighbors);
        for (size_t j = 0; j < count; ++j) {
            uint32_t neighborIndex = neighbors[j];
            Particle &neighbor = particles[neighborIndex];
            float r = sqrt(pow(neighbor.position[0] - p.position[0], 2) + pow(neighbor.position[1] - p.position[1], 2) + pow(neighbor.position[2] - p.position[2], 2));
            if (r < h) {
                float kernelValue = poly6Kernel(r, h);
                density += mass * kernelValue;
            }
        }
        density += selfDens * mass * poly6Kernel(0.0f, h);
        float pressure = 0.0f;
        if (density > restDensity) {
            pressure = gasConstant * (density - restDensity);
        }
        p.density = density;
        p.pressure = pressure;
    }
}

int main() {
    Particle particles[10];
    uint32_t particleTable[10];
    float mass = 1.0f, poly6 = 1.0f, h = 1.0f, h2 = 1.0f, selfDens = 1.0f, restDensity = 1.0f, gasConstant = 1.0f;
    for (int i = 0; i < 10; i++) {
        particles[i].position[0] = i;
        particles[i].position[1] = i;
        particles[i].position[2] = i;
    }
    parallelDensityAndPressures(particles, 10, 0, 10, particleTable, mass, poly6, h, h2, selfDens, restDensity, gasConstant);
    return 0;
}
